// Altre scelte di ogni giorno (italiano). Qualitative, nessuna statistica; cifre solo come timer («10 minuti»); nessuna cifra nelle scene.
// Formato di ogni idea: [chiave, titolo, titolo del consiglio (segue «Il mio consiglio:»), motivo 1, motivo 2, primo passo, etichetta breve, [scena 1 ora · sera · domani], [sensazione 1 ora · sera · domani]]
const build = (defs) => {
  const TEXT = {}, SC = {};
  for (const [cat, label, example, ideas] of defs) {
    TEXT[cat] = { label, example, ideas: {} };
    for (const [k, title, headline, w1, w2, step, tag, scenes, feels] of ideas) {
      TEXT[cat].ideas[k] = { title, headline, why: [w1, w2], step };
      SC[cat + '.' + k] = [tag, scenes, feels];
    }
  }
  return { TEXT, SC };
};

